//.....................Deep Immutability for State mangement.............................

type AppConfig = {
    api: { endpoint: string; retries: number };
    activeFeatures: string[];

}

type DeepReadonly<T> = {
    readonly [P in keyof T]: T[P] extends object ? DeepReadonly<T[P]> : T[P];
}

const globalConfig: DeepReadonly<AppConfig> = {
    api: { endpoint: "https://api.v1", retries: 3 },
    activeFeatures: ["new_dashboard"],
}

globalConfig.api = { endpoint: "v2", retries: 0 }

globalConfig.api.retries = 0;
globalConfig.activeFeatures.push("admin-bypass");

const instantConfig = {
    api: {endpoint: "https://api.v1", retries: 3},
    activeFeatures: ["new-dashboard"]
} as const;

instantConfig.api.retries = 0;